const { parse: parseHTML } = require('node-html-parser')

/**
 * AsciiDoc extension to handle subsection badges
 * Allows adding status badges (Preview, Beta, Deprecated, etc.) to section headings (h2-h6)
 *
 * Usage in AsciiDoc:
 *   [badge="Preview"]
 *   == Slack notifications
 *
 *   [badge="Beta",badge-classes="text-white bg-blue-500"]
 *   === New feature
 *
 *   [badge="Deprecated",badge-bg="#ff0000",badge-border="#cc0000"]
 *   ==== Old approach
 *
 * A badged section needs a resolvable id (explicit via `[#id]`, or
 * auto-generated by Asciidoctor from its title) so the badge can be located
 * and injected into the rendered output. Every current usage already pairs
 * `[#id]` with `[badge=...]`.
 *
 * Configuration in antora-playbook.yml:
 *   asciidoc:
 *     extensions:
 *     - ./extensions/subsection-badge-extension.js
 *
 * Implementation note: badges are injected into the final rendered HTML by a
 * Postprocessor, not by mutating the section's AsciiDoc title.
 *
 * Section titles are substituted lazily (inline formatting like `code` or
 * *bold* is converted to HTML on first read), and Asciidoctor caches that
 * substituted result. An earlier version of this extension appended the
 * badge markup directly to the title and called `section.title = ...`, which
 * clears that cache. The next time anything reads the title (for example,
 * the heading template during HTML conversion), Asciidoctor recomputes it —
 * substituting the ALREADY-substituted HTML a second time. That second pass
 * escapes the `<`/`>` characters from the first pass into literal text, so
 * any badged heading with inline formatting (for example, `*`with_tool_cache`*`)
 * rendered as visible, escaped markup instead of styled text.
 *
 * Injecting into the final HTML string instead avoids this entirely, since
 * nothing ever re-substitutes rendered output.
 */
module.exports.register = function register(registry, context = {}) {
  // Default configuration - can be overridden via context
  const config = {
    // Default badge CSS classes (matches page-level badge styling)
    defaultClasses: context.defaultClasses || 'text-[10px] rounded-full py-1 px-1.5 text-terminal-black border',
  }

  // Tag sections with badge metadata during tree processing. This runs
  // before the document is converted to HTML, so it must not touch the
  // title itself (see the note above).
  registry.treeProcessor(function () {
    this.process((doc) => {
      const sections = doc.findBy({ context: 'section' })

      sections.forEach((section) => {
        const badgeText = section.getAttribute('badge')
        if (!badgeText) return // Skip sections without badges

        if (!section.getId()) {
          console.warn(
            `subsection-badge-extension: section "${section.getTitle()}" has a badge attribute but no resolvable id; skipping badge injection.`
          )
          return
        }

        section.setAttribute('badge-pending-text', badgeText)
        section.setAttribute('badge-pending-classes', section.getAttribute('badge-classes') || config.defaultClasses)

        const badgeBg = section.getAttribute('badge-bg')
        const badgeBorder = section.getAttribute('badge-border')
        if (badgeBg) section.setAttribute('badge-pending-bg', badgeBg)
        if (badgeBorder) section.setAttribute('badge-pending-border', badgeBorder)
      })

      return doc
    })
  })

  // Inject the badge markup into the fully-rendered HTML output, after all
  // AsciiDoc substitutions have already happened, so it can never be
  // re-substituted.
  registry.postprocessor(function () {
    this.process((doc, output) => {
      const sections = doc.findBy({ context: 'section' }).filter((section) => section.getAttribute('badge-pending-text'))
      if (sections.length === 0) return output

      const root = parseHTML(output)

      sections.forEach((section) => {
        const heading = root.getElementById(section.getId())
        if (!heading) return // Heading not present in this output; don't fail the build over it.

        const badgeText = section.getAttribute('badge-pending-text')
        const badgeClasses = section.getAttribute('badge-pending-classes')
        const badgeBg = section.getAttribute('badge-pending-bg')
        const badgeBorder = section.getAttribute('badge-pending-border')

        let styleAttr = ''
        if (badgeBg || badgeBorder) {
          const styles = []
          if (badgeBg) styles.push(`background-color: ${badgeBg}`)
          if (badgeBorder) styles.push(`border-color: ${badgeBorder}`)
          styleAttr = ` style="${styles.join('; ')}"`
        }

        heading.insertAdjacentHTML('beforeend', ` <span class="subsection-badge ${badgeClasses}"${styleAttr}>${badgeText}</span>`)
      })

      return root.toString()
    })
  })
}
